 * Runs an instant-runoff count over a parsed election and returns the
 * sequence of rounds, per the counting rules described in the task.
 */

/**
 * Counts `candidates` (declared names) and `ballots`
 * (`{ count, ranking }` entries) round by round until a candidate wins
 * a majority of the active total or the active total drops to zero.
 * Returns an array of rounds, each `{ number, counts, exhausted,
 * eliminated, winner }`, where `counts` is a Map from continuing
 * candidate name to its vote count in that round.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let number = 0

  for (;;) {
    number++
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    history.push(counts)
    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    let winner = null
    if (activeTotal > 0) {
      for (const [name, count] of counts) {
        if (count * 2 > activeTotal) {
          winner = name
          break
        }
      }
    }

    if (activeTotal === 0) {
      rounds.push({ number, counts, exhausted, eliminated: null, winner: null })
      break
    }
    if (winner !== null) {
      rounds.push({ number, counts, exhausted, eliminated: null, winner })
      break
    }

    const min = Math.min(...counts.values())
    const tied = [...counts.keys()].filter((name) => counts.get(name) === min)
    const eliminated = selectElimination(tied, history)

    rounds.push({ number, counts, exhausted, eliminated, winner: null })
    continuing.delete(eliminated)
  }

  return rounds
}

/**
 * Breaks a tie for fewest votes among `tied` candidates by comparing
 * their vote counts across `history` (one Map per round counted so
 * far, earliest first), narrowing to the lowest scorers at the first
 * round where they differ and restarting the comparison from the
 * first round among the survivors. A tie that survives every round
 * is broken by eliminating whichever name sorts last by code point.
 */
function selectElimination(tied, history) {
  let current = tied.slice()
  let narrowed = true

  while (narrowed) {
    narrowed = false
    for (const roundCounts of history) {
      const values = current.map((name) => roundCounts.get(name))
      if (new Set(values).size > 1) {
        const min = Math.min(...values)
        current = current.filter((name) => roundCounts.get(name) === min)
        narrowed = true
        break
      }
    }
  }

  if (current.length === 1) return current[0]
  return current.reduce((last, name) => (name > last ? name : last))
}
